133	  return advertised.filter((name) => !name.startsWith(CORE_TOOL_PREFIX));
134	}
135	
136	/**
137	 * Hold one server's advertised tools to its set, exactly.
138	 *
139	 * Both directions, and the less obvious one earns its place: a `missing` tool is how
140	 * a server that came up empty, or one whose allowlist has gone from narrowing to
141	 * forbidding, becomes a failure rather than a pass over an empty list. An expectation
142	 * that only refused extras would be satisfied by a server offering nothing.
143	 */
144	export function compareToolSet(expected: ExactToolSet, advertised: readonly string[]): ToolSetMismatch | undefined {
145	  const seen = new Set(serverContributed(advertised));
146	  const allowed = new Set(expected.tools);
147	  const unexpected = [...seen].filter((name) => !allowed.has(name)).sort();
148	  const missing = expected.tools.filter((name) => !seen.has(name));
149	  if (unexpected.length === 0 && missing.length === 0) return undefined;
150	  return { server: expected.server, unexpected, missing };
151	}
