153	/** One line a person can act on, naming what changed and what it costs. */
154	export function describeMismatch(expected: ExactToolSet, mismatch: ToolSetMismatch): string {
155	  const parts: string[] = [];
156	  if (mismatch.unexpected.length > 0) {
157	    parts.push(`advertises ${mismatch.unexpected.join(", ")}, which it must not`);
158	  }
159	  if (mismatch.missing.length > 0) {
160	    parts.push(`does not advertise ${mismatch.missing.join(", ")}, which it must`);
